parameters.query:
DELETE FROM categories
WHERE category_id = {{ $json.params.categoryId }}
  AND NOT EXISTS (
    SELECT 1 FROM components WHERE category_id = {{ $json.params.categoryId }}
  )
RETURNING category_id;

