const items = $input.all();
const q = (items[0] && items[0].json && items[0].json.query) ? items[0].json.query : {};

const search = q.search || "";
const sortBy = q.sortBy || "category_name";
const limit = Number.isInteger(parseInt(q.pageSize)) ? parseInt(q.pageSize) : null;
const pageNo = Number.isInteger(parseInt(q.pageNo)) ? parseInt(q.pageNo) : 1;
const offset = limit ? (pageNo - 1) * limit : 0;

return [{ json: { params: { search, sortBy, limit, offset } } }];

const data = $input.item.json;

return [
  {
    json: {
      summary: {
        totalCategories: parseInt(data.total_categories) || 0,
        activeCategories: parseInt(data.active_categories) || 0,
        emptyCategories: parseInt(data.empty_categories) || 0,
        totalComponents: parseInt(data.total_components) || 0,
        recentAdditions: parseInt(data.recent_additions) || 0
      },
      statistics: {
        averageCategorySize: parseFloat(data.avg_category_size) || 0,
        largestCategorySize: parseInt(data.largest_category_size) || 0,
        largestCategoryName: data.largest_category_name || 'N/A',
        categoryCompleteness: data.total_categories > 0 ? Math.round((data.active_categories / data.total_categories) * 100) : 0
      },
      timeline: {
        latestComponentDate: data.latest_component_date,
        oldestComponentDate: data.oldest_component_date
      },
      insights: {
        hasEmptyCategories: parseInt(data.empty_categories) > 0,
        emptyPercentage: data.total_categories > 0 ? Math.round((data.empty_categories / data.total_categories) * 100) : 0,
        recentActivityRate: data.total_components > 0 ? Math.round((data.recent_additions / data.total_components) * 100) : 0,
        status: data.active_categories === data.total_categories ? 'All categories in use' : data.empty_categories > 0 ? 'Some unused categories' : 'Optimal'
      }
    }
  }
];

